package com.vinnot.ai.application.config;

import java.math.BigDecimal;
import java.util.Objects;

/**
 * Limits for the background refresh of stale AI profiles.
 *
 * @param profilesPerRun maximum profiles regenerated by one run
 * @param budgetShare    share of the monthly AI limit the refresh may use; the rest stays for user requests
 */
public record AiProfileRefreshPolicy(int profilesPerRun, BigDecimal budgetShare) {

    public AiProfileRefreshPolicy {
        Objects.requireNonNull(budgetShare);
        if (profilesPerRun < 1 || profilesPerRun > 20
                || budgetShare.signum() <= 0 || budgetShare.compareTo(BigDecimal.ONE) > 0) {
            throw new IllegalArgumentException("Invalid AI profile refresh limits");
        }
    }
}
